interface MyFormModel {
  verb: string;
}

@Component({
             //...
             imports: [
               InuRadioGroup
               FormField
             ]
           })
export class MyView {
  formModel = signal<MyFormModel>({
                                    verb: 'GET'
                                  });
  myForm = form(this.formModel, (path) => { });

  constructor() {
    toObservable(this.formModel)
      .pipe(
        debounceTime(200),
        distinctUntilChanged(),
        takeUntilDestroyed()
      )
      .subscribe(value => {
        this.onValueChanged(value)
      });
  }
  private onValueChanged(value: MyFormModel) {
    // ...
  }
}
